const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const PHOTO_DIR = '/var/lib/nixframe/photos';
// 12 MB: n8n's 16 MiB request cap (N8N_PAYLOAD_SIZE_MAX default) holds about 12 MB of file once base64 adds a third; the upload page uses the same limit.
const MAX_SIZE = 12 * 1000 * 1000;
// Declared MIME type -> ImageMagick coder. The coder is also what the file
// signature must prove, so the decoder is fixed rather than guessed.
const CODER_BY_MIME = {
  'image/jpeg': 'jpeg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/heic': 'heic',
  'image/heif': 'heic',
};
const HEIF_BRANDS = ['heic', 'heix', 'hevc', 'hevx', 'heim', 'heis', 'mif1', 'msf1', 'heif'];

// Generic messages for the client; details stay in the server log.
const MSG_FORMAT = 'Formatul pozei nu e acceptat. Folosește JPG, PNG, WebP sau HEIC.';
const MSG_TOO_LARGE = 'Poza e prea mare.';
const MSG_TIMEOUT = 'Poza a durat prea mult. Încearcă una mai mică.';
const MSG_UNREADABLE = 'Rama nu a putut citi formatul acestei poze. Încearcă altă poză.';
const MSG_FAILED = 'Poza nu a putut fi salvată. Încearcă din nou.';
const fail = error => [{ json: { success: false, error } }];

// Identify the image type from its first bytes; null when it is none of the four.
function sniffCoder(buf) {
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'jpeg';
  if (buf.length >= 8 && buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return 'png';
  if (buf.length >= 12 && buf.toString('latin1', 0, 4) === 'RIFF' && buf.toString('latin1', 8, 12) === 'WEBP') return 'webp';
  if (buf.length >= 12 && buf.toString('latin1', 4, 8) === 'ftyp' && HEIF_BRANDS.includes(buf.toString('latin1', 8, 12))) return 'heic';
  return null;
}

try {
  const body = $input.first().json.body || {};
  const imageData = body.imageData;

  if (!imageData || typeof imageData !== 'string') {
    return fail(MSG_FAILED);
  }

  // Extract base64 data and MIME type
  let mimeType = 'image/jpeg';
  let base64Data = imageData;

  if (imageData.startsWith('data:')) {
    const match = imageData.match(/^data:(image\/[^;]+);base64,(.+)$/);
    if (!match) {
      return fail(MSG_FORMAT);
    }
    mimeType = match[1];
    base64Data = match[2];
  }

  // Validate MIME type
  const coder = CODER_BY_MIME[mimeType];
  if (!coder) {
    return fail(MSG_FORMAT);
  }

  // Decode base64
  const buffer = Buffer.from(base64Data, 'base64');

  // Validate size
  if (buffer.length > MAX_SIZE) {
    return fail(MSG_TOO_LARGE);
  }

  // The file signature must match the declared type
  if (sniffCoder(buffer) !== coder) {
    return fail(MSG_FORMAT);
  }

  // Generate unique filename with timestamp
  const hash = crypto.createHash('sha256').update(buffer).digest('hex').substring(0, 8);
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-').substring(0, 19);
  const tmpId = crypto.randomUUID();

  const inputExt = { jpeg: '.jpg', png: '.png', webp: '.webp', heic: '.heic' }[coder];
  const outputExt = '.jpg'; // Always output JPEG for consistency

  // Write raw input to temp file
  const tmpInput = path.join(PHOTO_DIR, '.tmp-input-' + tmpId + inputExt);
  const tmpOutput = path.join(PHOTO_DIR, '.tmp-output-' + tmpId + outputExt);
  const finalName = timestamp + '_' + hash + outputExt;
  const finalPath = path.join(PHOTO_DIR, finalName);

  fs.writeFileSync(tmpInput, buffer);

  try {
    // Convert: auto-orient EXIF, strip metadata, convert HEIC→JPEG
    // Uses execFileSync (no shell) to avoid command injection risks.
    // The "<coder>:" prefix fixes the decoder to the verified type.
    try {
      execFileSync('convert', [coder + ':' + tmpInput, '-auto-orient', '-strip', tmpOutput], { timeout: 30000, stdio: ['pipe', 'pipe', 'pipe'] });
    } catch (convertErr) {
      const stderr = convertErr.stderr ? convertErr.stderr.toString() : '';
      console.error('convert failed:', (stderr.split('\n')[0] || convertErr.message || '').slice(0, 300));
      if (convertErr.killed || convertErr.signal === 'SIGTERM') {
        return fail(MSG_TIMEOUT);
      }
      return fail(MSG_UNREADABLE);
    }

    // Atomic rename to final location (prevents watcher from seeing partial file)
    fs.renameSync(tmpOutput, finalPath);
    fs.chmodSync(finalPath, 0o664);

    // Signal systemd.paths watcher — atomic rename() causes systemd to lose
    // the inotify watch on the new file (systemd bug #20934), so we use a trigger file
    fs.writeFileSync(path.join(PHOTO_DIR, '.trigger'), Date.now().toString());
  } finally {
    // Clean up temp files (ENOENT is expected if conversion succeeded)
    try { fs.unlinkSync(tmpInput); } catch (e) { if (e.code !== 'ENOENT') console.error('Failed to clean temp input:', e.message); }
    try { fs.unlinkSync(tmpOutput); } catch (e) { if (e.code !== 'ENOENT') console.error('Failed to clean temp output:', e.message); }
  }

  // Remove placeholder if real photos now exist
  const placeholderPath = path.join(PHOTO_DIR, '000-placeholder.png');
  try {
    const files = fs.readdirSync(PHOTO_DIR).filter(f => /\.(jpg|jpeg|png|webp)$/i.test(f) && !f.startsWith('.') && f !== '000-placeholder.png');
    if (files.length > 0 && fs.existsSync(placeholderPath)) {
      try { fs.unlinkSync(placeholderPath); } catch (unlinkErr) { console.error('Failed to remove placeholder:', unlinkErr.message); }
    }
  } catch (dirErr) {
    if (dirErr.code !== 'ENOENT') console.error('Failed to list photo directory for placeholder cleanup:', dirErr.message);
  }

  // Count photos for response
  const photoCount = fs.readdirSync(PHOTO_DIR).filter(f => /\.(jpg|jpeg|png|webp)$/i.test(f) && !f.startsWith('.')).length;

  return [{ json: { success: true, filename: finalName, photoCount } }];

} catch (err) {
  console.error('Upload failed:', err && err.message);
  return fail(MSG_FAILED);
}
